import type { KqSocialContentMessage, KqSocialContentPerson } from "./kanab-quest-social-content";
import type { KqSocialProducerChoice, KqSocialProducerNarrative } from "./kanab-quest-social-producer-types";

type Voice = [KqSocialContentPerson, string];
const replies = (a: Voice, b: Voice): KqSocialProducerChoice["replies"] => [a, b].map(([person, text]) => ({ id: "", person, text })) as KqSocialProducerChoice["replies"];
const choice = (
  label: string, description: string, upside: string, downside: string, outcome: string,
  post: string, a: Voice, b: Voice,
): KqSocialProducerChoice => ({ label, description, upside, downside, outcome, post, replies: replies(a, b) });
const posted = (post: string, a: Voice, b: Voice): Partial<KqSocialProducerChoice> => ({ post, replies: replies(a, b) });

